for reply_index, reply_spec in enumerate(SPEC["support_replies"], start=1):
    reply_matches = []
    if ticket_obj is not None:
        for path, obj in walk(ticket_obj, ticket_path):
            text = scalar(obj, ["text", "message", "content", "reply"])
            author_id = scalar(obj, ["userId", "user_id", "authorId", "author_id", "senderId"])
            role = scalar(obj, ["role", "authorRole", "senderRole"])
            if (
                same(text, reply_spec.get("text"))
                and (author_id is None or same(author_id, approved_id))
                and (role is None or same(role, reply_spec.get("role", "driver")))
            ):
                reply_matches.append((path, obj))
    for path, obj in nodes:
        linked_ticket_id = scalar(obj, ["ticketId", "ticket_id", "supportTicketId"])
        text = scalar(obj, ["text", "message", "content", "reply"])
        author_id = scalar(obj, ["userId", "user_id", "authorId", "author_id", "senderId"])
        role = scalar(obj, ["role", "authorRole", "senderRole"])
        if (
            same(linked_ticket_id, ticket_id)
            and same(text, reply_spec.get("text"))
            and (author_id is None or same(author_id, approved_id))
            and (role is None or same(role, reply_spec.get("role", "driver")))
        ):
            reply_matches.append((path, obj))
    unique_reply_paths = sorted({item[0] for item in reply_matches})
    add(
        f"driver_support_reply_{reply_index}",
        len(unique_reply_paths) == 1,
        {
            "ticket_id": ticket_id,
            "text": reply_spec.get("text"),
            "author_id": approved_id,
            "role": reply_spec.get("role", "driver"),
        },
        {
            "match_count": len(unique_reply_paths),
            "paths": unique_reply_paths,
        },
        unique_reply_paths[0] if len(unique_reply_paths) == 1 else None,
        "The exact reply was not found as a nested or ticket-linked structured record.",
    )

